        // Submit and verify\r\n        ActionResult submitResult = action.click(submitButton);\r\n        if (!submitResult.isSuccess()) {\r\n            log.error("Submit button not found");\r\n            return false;\r\n        }\r\n\r\n        action.vanish(loadingSpinner);\r\n        return action.find(successMessage).isSuccess();\r\n    }\r\n\r\n    /**\r\n     * Demonstrates mixing convenience methods with traditional API.\r\n     * Shows when to use each approach.\r\n     */\r\n    public void demonstrateMixedApproach() {\r\n        log.info("Demonstrating mixed approach");\r\n\r\n        // Simple operation - use convenience method\r\n        ActionResult findResult = action.find(usernameField);\r\n\r\n        // Complex operation - use traditional API with full configuration\r\n        if (findResult.isSuccess()) {\r\n            action.highlight(findResult.getBestMatch().get().getRegion());\r\n            log.info("Username field highlighted");\r\n        }\r\n    }\r\n}\n'})}),"\n",(0,r.jsx)(n.p,{children:"This example is fully compilable and demonstrates:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Complete Spring setup"})," with ",(0,r.jsx)(n.code,{children:"@Component"})," and ",(0,r.jsx)(n.code,{children:"@Autowired"})]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"StateImage initialization"})," with proper builders"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Basic convenience methods"})," (click, type, find, vanish)"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"StateString usage"})," with convenience methods"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Error handling"})," with ActionResult checks"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Logging"})," at appropriate levels"]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Production-ready structure"})," that can be deployed imm